 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  const customer = customerResult.value;

  // Validate issueDate format and reality
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate and normalize terms
  const normalizedTerms = terms || 'NET30';
  if (!['NET14', 'NET30', 'EOM'].includes(normalizedTerms)) {
    return fail('TERMS_INVALID');
  }

  // Calculate due date
  const dueDate = calculateDueDate(issueDate, normalizedTerms);

  // Validate lines array is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and expand all line items
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount
    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) return fail(discountValidation.error);

    // Look up product
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;

    // Apply tier discount if no explicit discount is provided
    const discountPercent =
      line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];

    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    terms: normalizedTerms,
    dueDate,
    lines: invoiceLines,
  });
}

